//! Right-click menu for the writing surface. The web app relies on the
//! webview's own editable-text menu; GPUI has none, so the native editor
//! offers the same clipboard and history commands plus Twyne's margin note,
//! all dispatched through the editor's existing actions and key hints.

use gpui_kit::component::menu::{ContextMenu, ContextMenuExt, PopupMenu};
use gpui_kit::prelude::*;
use gpui_kit::{Context, MouseDownEvent, Stateful, WeakEntity, Window, div};

use super::{
    Bold, Copy, Cut, Italic, Paste, Redo, RichEditorEvent, RichEditorView, SelectAll, Underline,
    Undo,
};

gpui_kit::actions!(twyne_rich_editor_menu, [CommentOnSelection]);

/// What the menu needs from the editor at the moment it opens.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct MenuState {
    pub editable: bool,
    pub has_selection: bool,
    pub can_undo: bool,
    pub can_redo: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum MenuEntry {
    Cut,
    Copy,
    Paste,
    Bold,
    Italic,
    Underline,
    Comment,
    Undo,
    Redo,
    SelectAll,
}

impl MenuEntry {
    fn label(self) -> &'static str {
        match self {
            Self::Cut => "Cut",
            Self::Copy => "Copy",
            Self::Paste => "Paste",
            Self::Bold => "Bold",
            Self::Italic => "Italic",
            Self::Underline => "Underline",
            Self::Comment => "Comment on selection",
            Self::Undo => "Undo",
            Self::Redo => "Redo",
            Self::SelectAll => "Select all",
        }
    }

    fn action(self) -> Box<dyn gpui_kit::Action> {
        match self {
            Self::Cut => Box::new(Cut),
            Self::Copy => Box::new(Copy),
            Self::Paste => Box::new(Paste),
            Self::Bold => Box::new(Bold),
            Self::Italic => Box::new(Italic),
            Self::Underline => Box::new(Underline),
            Self::Comment => Box::new(CommentOnSelection),
            Self::Undo => Box::new(Undo),
            Self::Redo => Box::new(Redo),
            Self::SelectAll => Box::new(SelectAll),
        }
    }

    fn enabled(self, state: MenuState) -> bool {
        match self {
            Self::Cut | Self::Comment => state.editable && state.has_selection,
            Self::Copy => state.has_selection,
            Self::Paste | Self::Bold | Self::Italic | Self::Underline => state.editable,
            Self::Undo => state.editable && state.can_undo,
            Self::Redo => state.editable && state.can_redo,
            Self::SelectAll => true,
        }
    }
}

/// Groups in display order; separators fall between them. Formatting only
/// appears where it can apply, as in the browser's own editable menu.
pub(super) fn groups(state: MenuState) -> Vec<Vec<MenuEntry>> {
    let mut groups = vec![vec![MenuEntry::Cut, MenuEntry::Copy, MenuEntry::Paste]];
    if state.editable {
        groups.push(vec![
            MenuEntry::Bold,
            MenuEntry::Italic,
            MenuEntry::Underline,
        ]);
        groups.push(vec![MenuEntry::Comment]);
        groups.push(vec![MenuEntry::Undo, MenuEntry::Redo]);
    }
    groups.push(vec![MenuEntry::SelectAll]);
    groups
}

impl RichEditorView {
    pub(super) fn context_menu_state(&self) -> MenuState {
        MenuState {
            editable: !self.is_read_only(),
            has_selection: !self.selection().is_empty(),
            can_undo: self.can_undo(),
            can_redo: self.can_redo(),
        }
    }

    /// A right press outside the selection moves the caret there, so the menu
    /// acts on the passage under the pointer; inside it, the selection stays.
    pub(super) fn context_mouse_down(
        &mut self,
        event: &MouseDownEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.drag.is_active() {
            self.cancel_block_drag(window, cx);
            return;
        }
        window.focus(&self.focus, cx);
        let Some(offset) = self.index_at_point(event.position) else {
            return;
        };
        if !self.selection().range().contains(&offset) {
            self.move_to(offset, false, cx);
        }
    }

    pub(super) fn comment_on_selection(&mut self, cx: &mut Context<Self>) {
        let selection = self.selection();
        if self.is_read_only() || selection.is_empty() {
            return;
        }
        cx.emit(RichEditorEvent::CommentSelectionRequested { selection });
    }
}

pub(super) fn attach(
    element: Stateful<gpui_kit::Div>,
    view: WeakEntity<RichEditorView>,
    focus: gpui_kit::FocusHandle,
) -> ContextMenu<Stateful<gpui_kit::Div>> {
    element.context_menu(move |menu: PopupMenu, _, cx| {
        let Some(state) = view
            .upgrade()
            .map(|view| view.read(cx).context_menu_state())
        else {
            return menu;
        };
        let mut menu = menu.action_context(focus.clone()).min_w(px(200.));
        for group in groups(state) {
            menu = menu.separator();
            for entry in group {
                menu = menu.menu_with_disabled(entry.label(), entry.action(), !entry.enabled(state));
            }
        }
        menu
    })
}

#[allow(dead_code)]
fn _placeholder() -> gpui_kit::Div {
    div()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn state(editable: bool, has_selection: bool) -> MenuState {
        MenuState {
            editable,
            has_selection,
            can_undo: true,
            can_redo: false,
        }
    }

    #[test]
    fn read_only_menu_offers_only_copy_and_select_all() {
        let groups = groups(state(false, true));
        assert_eq!(
            groups,
            vec![
                vec![MenuEntry::Cut, MenuEntry::Copy, MenuEntry::Paste],
                vec![MenuEntry::SelectAll],
            ]
        );
        let enabled: Vec<_> = groups
            .concat()
            .into_iter()
            .filter(|entry| entry.enabled(state(false, true)))
            .collect();
        assert_eq!(enabled, vec![MenuEntry::Copy, MenuEntry::SelectAll]);
    }

    #[test]
    fn caret_without_selection_disables_selection_commands() {
        let caret = state(true, false);
        for entry in [MenuEntry::Cut, MenuEntry::Copy, MenuEntry::Comment] {
            assert!(!entry.enabled(caret), "{entry:?}");
        }
        for entry in [MenuEntry::Paste, MenuEntry::Bold, MenuEntry::Undo] {
            assert!(entry.enabled(caret), "{entry:?}");
        }
        assert!(!MenuEntry::Redo.enabled(caret));
    }
}

