    cx.update(|cx| {
        gpui_kit::init(cx);
        crate::theme::apply(cx).unwrap();
        let (window, paper) = gpui_kit::open_window(
            WindowOptions {
                window_bounds: Some(WindowBounds::Windowed(Bounds::new(
                    Point::default(),
                    size(px(720.), px(900.)),
                ))),
                ..Default::default()
            },
            cx,
            |_, cx| {
                cx.new(|cx| {
                    DragPaper(cx.new(|cx| {
                        let mut view = RichEditorView::new(document, cx);
                        view.set_opening_initial(
                            OpeningInitial {
                                mode: InitialMode::Off,
                                ..OpeningInitial::default()
                            },
                            cx,
                        );
                        view
                    }))
                })
            },
        )
        .unwrap();
        (window, paper.read(cx).0.clone())
    })
}

fn pointer_drag_start(
    window: &mut gpui_kit::Window,
    position: Point<gpui_kit::Pixels>,
    cx: &mut gpui_kit::App,
) {
    use gpui_kit::{InputEvent, MouseButton, MouseDownEvent, MouseMoveEvent};
    for event in [
        MouseMoveEvent {
            position,
            pressed_button: None,
            modifiers: Default::default(),
        }
        .to_platform_input(),
        MouseDownEvent {
            position,
            button: MouseButton::Left,
            modifiers: Default::default(),
            click_count: 1,
            first_mouse: false,
        }
        .to_platform_input(),
        MouseMoveEvent {
            position: position + point(px(12.), px(0.)),
            pressed_button: Some(MouseButton::Left),
            modifiers: Default::default(),
        }
        .to_platform_input(),
    ] {
        window.dispatch_event(event, cx);
        window.render_frame(cx);
    }
}

fn pointer_drag_move(
    window: &mut gpui_kit::Window,
    position: Point<gpui_kit::Pixels>,
    release: bool,
    cx: &mut gpui_kit::App,
) {
    use gpui_kit::{InputEvent, MouseButton, MouseMoveEvent, MouseUpEvent};
    window.dispatch_event(
        MouseMoveEvent {
            position,
            pressed_button: Some(MouseButton::Left),
            modifiers: Default::default(),
        }
        .to_platform_input(),
        cx,
    );
    window.render_frame(cx);
    if release {
        window.dispatch_event(
            MouseUpEvent {
                position,
                button: MouseButton::Left,
                modifiers: Default::default(),
                click_count: 1,
            }
            .to_platform_input(),
            cx,
        );
        window.render_frame(cx);
    }
}

