#[gpui_kit::test]
fn mounted_right_click_keeps_selection_and_menu_requests_a_margin_note(cx: &mut TestAppContext) {
    use std::{cell::RefCell, rc::Rc};
    let (handle, view) = drag_room(cx, "<p>First passage here</p><p>Second passage</p>");
    let events = Rc::new(RefCell::new(Vec::new()));
    let received = events.clone();
    cx.update(|cx| {
        cx.subscribe(&view, move |_, event: &RichEditorEvent, _| {
            if let RichEditorEvent::CommentSelectionRequested { selection } = event {
                received.borrow_mut().push(*selection);
            }
        })
        .detach()
    });
    // The menu is built in a deferred callback, so each press ends its update.
    let mut step = |cx: &mut TestAppContext, f: &mut dyn FnMut(&mut gpui_kit::Window, &mut gpui_kit::App)| {
        cx.update_window(handle, |_, window, cx| f(window, cx)).unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| window.render_frame(cx)).unwrap();
    };

    // A right press outside the selection moves the caret under the pointer.
    step(cx, &mut |window, cx| {
        view.update(cx, |view, cx| view.set_selection(Selection::new(0, 5), cx).unwrap());
        window.render_frame(cx);
        let second = view.read(cx).placed.borrow().get(&vec![1]).unwrap().bounds;
        right_press(window, point(second.left() + px(2.), second.center().y), cx);
    });
    step(cx, &mut |window, cx| {
        // "First passage here" is 18 characters; the second paragraph opens at 19.
        assert_eq!(view.read(cx).selection(), Selection::new(19, 19));
        assert!(window.try_find("popup-menu").is_some());
        window.press("escape", cx);
    });

    // Inside the selection, the passage stays selected for the menu.
    step(cx, &mut |window, cx| {
        assert!(window.try_find("popup-menu").is_none());
        view.update(cx, |view, cx| view.set_selection(Selection::new(0, 5), cx).unwrap());
        window.render_frame(cx);
        let first = view.read(cx).placed.borrow().get(&vec![0]).unwrap().bounds;
        right_press(window, point(first.left() + px(4.), first.center().y), cx);
    });
    step(cx, &mut |window, cx| {
        assert_eq!(view.read(cx).selection(), Selection::new(0, 5));
        // Items are indexed in display order, separators included.
        let comment = (0..16usize)
            .find(|ix| {
                window
                    .within("popup-menu")
                    .try_find(*ix)
                    .is_some_and(|item| item.label() == Some("Comment on selection"))
            })
            .expect("Comment item");
        window.within("popup-menu").click(comment, cx);
    });
    assert_eq!(events.borrow().as_slice(), [Selection::new(0, 5)]);
}
