    /// The menu opens on release, as the platform's own editable menus do.
    pub(super) fn context_mouse_up(
        &mut self,
        event: &MouseUpEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let state = self.context_menu_state();
        let focus = self.focus.clone();
